# area: self_classmethods
# hypothesis: A classmethod used as an alternative constructor returns an instance of the class it is called on, so a checker should infer Self-typed results for cls-based construction.
from typing import Self, reveal_type


class Point:
    def __init__(self, x: int, y: int) -> None:
        self.x = x
        self.y = y

    @classmethod
    def origin(cls) -> Self:
        return cls(0, 0)

    @classmethod
    def from_pair(cls, pair: tuple[int, int]) -> Self:
        return cls(*pair)

    @property
    def norm1(self) -> int:
        return abs(self.x) + abs(self.y)


class Point3(Point):
    def __init__(self, x: int, y: int, z: int = 0) -> None:
        super().__init__(x, y)
        self.z = z


p = Point.from_pair((3, -4))
reveal_type(p)
print(p.norm1)
q = Point3.origin()
reveal_type(q)
print(type(q).__name__, q.x, q.y)
print(type(Point3.from_pair((1, 2))).__name__)
